+import { listDeployEvents, type DeployEvent } from "./deploy-events.js";
+
+export async function currentDeployState(
+  environment: string,
+  fetchJson: (url: string) => Promise<DeployEvent[]>,
+): Promise<DeployEvent["state"] | "unknown"> {
+  const events = await listDeployEvents(environment, fetchJson);
+  const latest = events[events.length - 1];
+  return latest ? latest.state : "unknown";
+}

