+import { listReviews, type ReviewRecord } from "./review-api.js";
+
+export async function hasOutstandingChangeRequest(
+  pullNumber: number,
+  fetchJson: (url: string) => Promise<ReviewRecord[]>,
+): Promise<boolean> {
+  const reviews = await listReviews(pullNumber, fetchJson);
+  const latestByUser = new Map<string, ReviewRecord["state"]>();
+  for (const review of reviews) {
+    latestByUser.set(review.user, review.state);
+  }
+  return [...latestByUser.values()].includes("CHANGES_REQUESTED");
+}

