+import { parseCheckerLine } from "./checker-output.js";
+
+export function countProblems(output: string): { errors: number; warnings: number } {
+  const counts = { errors: 0, warnings: 0 };
+  for (const line of output.split("\n")) {
+    const record = parseCheckerLine(line);
+    if (record?.level === "error") {
+      counts.errors += 1;
+    } else if (record !== undefined) {
+      counts.warnings += 1;
+    }
+  }
+  return counts;
+}

